import {readFileSync,writeFileSync,existsSync} from 'node:fs';
const plan=JSON.parse(readFileSync(process.argv[2],'utf8'));
const result={schemaVersion:1,status:'RUNNING',cells:[]};
for(const cell of plan.cells){
 if(cell.report&&existsSync(cell.report))throw Error('Existing report '+cell.report);
 console.log('START '+cell.id+' '+new Date().toISOString());
 const started=performance.now();
 const child=Bun.spawn(cell.command,{cwd:cell.cwd,stdout:'pipe',stderr:'pipe'});
 const [exitCode,stdout,stderr]=await Promise.all([child.exited,new Response(child.stdout).text(),new Response(child.stderr).text()]);
 const guardLine=stderr.split('\n').find(x=>x.startsWith('HEAVY_GATE '));
 const guardian=guardLine?JSON.parse(guardLine.slice(11)):null;
 const passed=exitCode===0&&(!guardian||guardian.status==='PASS')&&(cell.expectedStdout===undefined||stdout===cell.expectedStdout);
 result.cells.push({...cell,exitCode,elapsedMs:performance.now()-started,stdout,stderr,guardian,passed});
 writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');
 console.log('FINISH '+cell.id+' '+(passed?'PASS':'FAIL')+' '+new Date().toISOString());
 if(!passed){result.status='FAILED_CELL_RETAINED';writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');process.exit(exitCode||1);}
}
result.status='ALL_CELLS_FINISHED';writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({status:result.status,cells:result.cells.length,output:plan.output}));

import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {Worker,isMainThread,workerData} from 'node:worker_threads';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {runTemplateSteps,runCheckerSteps,runCheckedInspectionSteps,runLibraryEmitterSteps,sourceFilesFor,COMPILED_SOURCE_FILE_TAG} from 'file:///Users/ilyagulya/Projects/My/bend/evals/checker_core_step_runtime.mjs';
const hash=path=>createHash('sha256').update(readFileSync(path)).digest('hex');
if(isMainThread){
 const [request,report]=process.argv.slice(2);if(!request||!report||existsSync(report))throw Error('Expected request and fresh report');
 const worker=new Worker(new URL(import.meta.url),{workerData:{request,report},resourceLimits:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}});
 await new Promise((done,reject)=>{worker.once('error',reject);worker.once('exit',code=>code===0?done():reject(Error('Readback worker exit '+code)));});
}else{
 const request=JSON.parse(readFileSync(workerData.request,'utf8')),tag=x=>x?.$?.split('.').at(-1),list=values=>values.reduceRight((tail,head)=>({$:'Con',head,tail}),{$:'Nil'});
 const verify=()=>{for(const[path,digest]of Object.entries(request.pins))if(hash(path)!==digest)throw Error('Pinned input drift '+path);};
 const result={schemaVersion:1,status:'RUNNING',diagnosticOnly:true,acceptanceEvidence:false,performanceEvidence:false,stages:[],image:request.image,imageSha256:hash(request.image),source:request.file,sourceSha256:hash(request.file),outputPatches:0,astReplay:false,compilerBootstrapGreen:false,selfhostGreen:false};
 const save=()=>writeFileSync(workerData.report,JSON.stringify(result,null,2)+'\n');
 const mark=(phase,status)=>{result.stages.push({phase,status});save();};
 try{
  verify();const component=(await import(pathToFileURL(request.image).href)).default;
  const end=Object.freeze({$:'FeedbackFuelEnd'}),prototype={get tail(){return fuel(this.remaining-1);}};
  const fuel=n=>{if(n===0)return end;const value=Object.create(prototype);value.$='FeedbackFuelCell';value.remaining=n;return value;};
  let feedback=component.parse_with_fuel(fuel(2000000),request.file,readFileSync(request.file,'utf8'));
  if(tag(feedback)!=='FeedbackComplete'||tag(feedback.value.result)!=='ParseSuccess')throw Error('Own parsing failed');
  let modules=list([component.parsed_module('',feedback.value.result.module)]);feedback=undefined;mark('own-parse','ParseSuccess');
  let expanded=runTemplateSteps({...component,expand_modules_start:input=>{modules=undefined;return component.expand_modules_start(input);}},modules);
  if(tag(expanded)!=='ExpandSuccess')throw Error('Own expansion failed');mark('own-expand',tag(expanded));
  let checked=runCheckerSteps({...component,check_expanded_start:input=>{expanded=undefined;return component.check_expanded_start(input);}},expanded.modules);
  if(tag(checked)!=='CheckSuccess')throw Error('Own check failed');mark('own-check',tag(checked));
  let inspection=runCheckedInspectionSteps({...component,inspect_checked_start:program=>{checked=undefined;return component.inspect_checked_start(program);}},checked.program);
  if(tag(inspection)!=='Inspection')throw Error('Own inspection failed '+tag(inspection));mark('own-inspection',tag(inspection));
  // Consume reconstructed AST, not the original CheckedProgram: a bad readback
  // cannot be hidden by forwarding the untouched original owner to the emitter.
  const recovered=inspection.modules;inspection=undefined;
  let rechecked=runCheckerSteps(component,recovered);
  if(tag(rechecked)!=='CheckSuccess')throw Error('Rechecking actual readback failed');mark('own-readback-recheck',tag(rechecked));
  const names=['zero','one','pack','make_pack','apply','identity','identity_probe','erased_probe','specialized_probe','local_twice','local_unused','local_order','over_order','over_generic','constructor_match'];
  const files=sourceFilesFor(request.file,[],COMPILED_SOURCE_FILE_TAG);
  const emitted=runLibraryEmitterSteps({...component,emit_library_start:(program,exports,sources)=>{rechecked=undefined;return component.emit_library_start(program,exports,sources);}},rechecked.program,list(names),files);
  if(tag(emitted)!=='EmitSuccess')throw Error('Readback library emission failed');
  if(existsSync(request.artifact))throw Error('Existing artifact');writeFileSync(request.artifact,emitted.source,{flag:'wx'});result.artifact={path:request.artifact,sha256:hash(request.artifact),bytes:Buffer.byteLength(emitted.source)};mark('own-readback-library-emission','EmitSuccess');
  const api=(await import(pathToFileURL(request.artifact).href)).default;if(!api||Object.keys(api).sort().join(',')!==[...names].sort().join(','))throw Error('Incorrect real consumer exports');
  const rows=[],bit=value=>{if(!['BitZero','BitOne'].includes(tag(value)))throw Error('Invalid Bit');return tag(value);},duo=value=>{if(tag(value)!=='Duo')throw Error('Invalid Duo');return[bit(value.left),bit(value.right)];};
  const expect=(name,observed,expected)=>{if(JSON.stringify(observed)!==JSON.stringify(expected))throw Error(name+':'+JSON.stringify(observed));rows.push({name,observed,expected,passed:true});};
  const zero=api.zero(),one=api.one();expect('zero-nullary',bit(zero),'BitZero');expect('one-nullary',bit(one),'BitOne');
  expect('positional-noncommutative',duo(api.pack(one,zero)),['BitOne','BitZero']);expect('positional-reversed-input',duo(api.pack(zero,one)),['BitZero','BitOne']);
  const partial=api.pack(one);expect('pack-one-argument-is-curried-function',typeof partial,'function');expect('pack-curried-second-argument',duo(partial(zero)),['BitOne','BitZero']);
  const higher=api.make_pack(one);expect('returned-curried-function',typeof higher,'function');expect('higher-order-positional-call',duo(api.apply(higher,zero)),['BitOne','BitZero']);expect('over-applied-returned-function',duo(api.make_pack(one,zero)),['BitOne','BitZero']);
  let liveCalls=0;expect('live-host-callback',duo(api.apply(value=>{liveCalls++;return api.pack(value,one);},zero)),['BitZero','BitOne']);expect('live-host-callback-evaluated-once',liveCalls,1);
  expect('erased-kind-and-type-effective-one-argument',bit(api.identity(one)),'BitOne');expect('ordinary-type-reference-erasure-in-bend-application',bit(api.identity_probe(zero)),'BitZero');expect('actual-template-specialization',bit(api.specialized_probe(one)),'BitOne');
  let erasedCalls=0;const poison=()=>{erasedCalls++;throw Error('Erased expression evaluated');};expect('erased-expression-keeps-second-live-argument',bit(api.erased_probe(poison,one)),'BitOne');expect('erased-expression-not-evaluated',erasedCalls,0);
  let localCalls=0;expect('shared-local-value',duo(api.local_twice(()=>{localCalls++;return one;},zero)),['BitOne','BitOne']);expect('shared-local-evaluated-once',localCalls,1);
  let unusedCalls=0;expect('unused-local-result',bit(api.local_unused(()=>{unusedCalls++;return one;},zero)),'BitZero');expect('unused-live-local-still-evaluated',unusedCalls,1);
  const localOrder=[];expect('ordered-local-values',duo(api.local_order(()=>{localOrder.push('first');return one;},()=>{localOrder.push('second');return zero;},zero,one)),['BitOne','BitZero']);expect('local-evaluation-order',localOrder,['first','second']);
  const namedOrder=[];expect('named-over-application-value',duo(api.over_order(()=>{namedOrder.push('callee');return one;},()=>{namedOrder.push('argument');return zero;},zero,one)),['BitOne','BitZero']);expect('named-over-application-order',namedOrder,['callee','argument']);
  const genericOrder=[];expect('generic-over-application-value',duo(api.over_generic(left=>{genericOrder.push('callee');return right=>{genericOrder.push('apply');return api.pack(left,right);};},()=>{genericOrder.push('argument');return zero;},one,one)),['BitOne','BitZero']);expect('generic-over-application-order',genericOrder,['callee','argument','apply']);
  expect('constructor-eliminator-first-arm',bit(api.constructor_match(zero)),'BitOne');expect('constructor-eliminator-default-chain',bit(api.constructor_match(one)),'BitZero');
  if(hash(request.artifact)!==result.artifact.sha256)throw Error('Consumer artifact modified');verify();result.runtimeRows=rows;result.artifactExecutedUnchanged=true;result.status='PASS_ACTUAL_INSPECTION_RECHECK_AND_LIBRARY_CONSUMERS';save();console.log(JSON.stringify({status:result.status,rows:rows.length,artifact:result.artifact}));
 }catch(error){result.status='FAIL_RETAINED';result.error=String(error);save();throw error;}
}
